Here is the commit message:
cachefiles: cyclic allocation of msg_id to avoid reuse

Reusing the msg_id after a maliciously completed reopen request may cause
a read request to remain unprocessed and result in a hung, as shown below:

       t1       |      t2       |      t3
-------------------------------------------------
cachefiles_ondemand_select_req
 cachefiles_ondemand_object_is_close(A)
 cachefiles_ondemand_set_object_reopening(A)
 queue_work(fscache_object_wq, &info->work)
                ondemand_object_worker
                 cachefiles_ondemand_init_object(A)
                  cachefiles_ondemand_send_req(OPEN)
                    // get msg_id 6
                    wait_for_completion(&req_A->done)
cachefiles_ondemand_daemon_read
 // read msg_id 6 req_A
 cachefiles_ondemand_get_fd
 copy_to_user
                                // Malicious completion msg_id 6
                                copen 6,-1
                                cachefiles_ondemand_copen
                                 complete(&req_A->done)
                                 // will not set the object to close
                                 // because ondemand_id && fd is valid.

                // ondemand_object_worker() is done
                // but the object is still reopening.

                                // new open req_B
                                cachefiles_ondemand_init_object(B)
                                 cachefiles_ondemand_send_req(OPEN)
                                 // reuse msg_id 6
process_open_req
 copen 6,A.size
 // The expected failed copen was executed successfully

Expect copen to fail, and when it does, it closes fd, which sets the
object to close, and then close triggers reopen again. However, due to
msg_id reuse resulting in a successful copen, the anonymous fd is not
closed until the daemon exits. Therefore read requests waiting for reopen
to complete may trigger hung task.

To avoid this issue, allocate the msg_id cyclically to avoid reusing the
msg_id for a very short duration of time.

Fixes: c8383054506c ("cachefiles: notify the user daemon when looking up cookie")
Signed-off-by: Baokun Li <libaokun1@huawei.com>
Link: https://lore.kernel.org/r/20240628062930.2467993-9-libaokun@huaweicloud.com
Acked-by: Jeff Layton <jlayton@kernel.org>
Reviewed-by: Gao Xiang <hsiangkao@linux.alibaba.com>
Reviewed-by: Jia Zhu <zhujia.zj@bytedance.com>
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The bug is caused by the reuse of `msg_id` after a maliciously completed reopen request, which can lead to a situation where a read request remains unprocessed, resulting in a hung state. This occurs because the system may mistakenly treat a stale `msg_id` as valid, allowing the daemon to successfully process requests that should not be valid anymore.

Here is the patch:

 static int cachefiles_ondemand_send_req(struct cachefiles_object *object,
 					enum cachefiles_opcode opcode,
 					size_t data_len,
 					init_req_fn init_req,
 					void *private)
 {
 	struct cachefiles_cache *cache = object->volume->cache;
 	struct cachefiles_req *req = NULL;
 	XA_STATE(xas, &cache->reqs, 0);
 	int ret;

 	if (!test_bit(CACHEFILES_ONDEMAND_MODE, &cache->flags))
 		return 0;

 	if (test_bit(CACHEFILES_DEAD, &cache->flags)) {
 		ret = -EIO;
 		goto out;
 	}

 	req = kzalloc(sizeof(*req) + data_len, GFP_KERNEL);
 	if (!req) {
 		ret = -ENOMEM;
 		goto out;
 	}

 	req->object = object;
 	init_completion(&req->done);
 	req->msg.opcode = opcode;
 	req->msg.len = sizeof(struct cachefiles_msg) + data_len;

 	ret = init_req(req, private);
 	if (ret)
 		goto out;

 	do {
 		/*
 		 * Stop enqueuing the request when daemon is dying. The
 		 * following two operations need to be atomic as a whole.
 		 *   1) check cache state, and
 		 *   2) enqueue request if cache is alive.
 		 * Otherwise the request may be enqueued after xarray has been
 		 * flushed, leaving the orphan request never being completed.
 		 *
 		 * CPU 1			CPU 2
 		 * =====			=====
 		 *				test CACHEFILES_DEAD bit
 		 * set CACHEFILES_DEAD bit
 		 * flush requests in the xarray
 		 *				enqueue the request
 		 */
 		xas_lock(&xas);

 		if (test_bit(CACHEFILES_DEAD, &cache->flags) ||
 		    cachefiles_ondemand_object_is_dropping(object)) {
 			xas_unlock(&xas);
 			ret = -EIO;
 			goto out;
 		}

 		/* coupled with the barrier in cachefiles_flush_reqs() */
 		smp_mb();

 		if (opcode == CACHEFILES_OP_CLOSE &&
-			!cachefiles_ondemand_object_is_open(object)) {
+		    !cachefiles_ondemand_object_is_open(object)) {
 			WARN_ON_ONCE(object->ondemand->ondemand_id == 0);
 			xas_unlock(&xas);
 			ret = -EIO;
 			goto out;
 		}

-		xas.xa_index = 0;
+		/*
+		 * Cyclically find a free xas to avoid msg_id reuse that would
+		 * cause the daemon to successfully copen a stale msg_id.
+		 */
+		xas.xa_index = cache->msg_id_next;
 		xas_find_marked(&xas, UINT_MAX, XA_FREE_MARK);
+		if (xas.xa_node == XAS_RESTART) {
+			xas.xa_index = 0;
+			xas_find_marked(&xas, cache->msg_id_next - 1, XA_FREE_MARK);
+		}
 		if (xas.xa_node == XAS_RESTART)
 			xas_set_err(&xas, -EBUSY);
+
 		xas_store(&xas, req);
-		xas_clear_mark(&xas, XA_FREE_MARK);
-		xas_set_mark(&xas, CACHEFILES_REQ_NEW);
+		if (xas_valid(&xas)) {
+			cache->msg_id_next = xas.xa_index + 1;
+			xas_clear_mark(&xas, XA_FREE_MARK);
+			xas_set_mark(&xas, CACHEFILES_REQ_NEW);
+		}
 		xas_unlock(&xas);
 	} while (xas_nomem(&xas, GFP_KERNEL));

 	ret = xas_error(&xas);
 	if (ret)
 		goto out;

 	wake_up_all(&cache->daemon_pollwq);
 	wait_for_completion(&req->done);
 	ret = req->error;
 	kfree(req);
 	return ret;
 out:
 	/* Reset the object to close state in error handling path.
 	 * If error occurs after creating the anonymous fd,
 	 * cachefiles_ondemand_fd_release() will set object to close.
 	 */
 	if (opcode == CACHEFILES_OP_OPEN &&
 	    !cachefiles_ondemand_object_is_dropping(object))
 		cachefiles_ondemand_set_object_close(object);
 	kfree(req);
 	return ret;
 }



